def unique_jobs(rows):
    # rows is a list of dicts with keys: source, source_id (may be None or ''), title
    seen = {}
    result = []  # maintain order via insertion when first seen
    for r in rows:
        key = (r['source'], r['source_id'])  # includes None/'' as is; stable dedup by exact tuple
        if key not in seen:  # keep first occurrence only
            seen[key] = True
            result.append(r)
    return result
